    conv._weights, conv._bias = snap["conv"]["weights"], snap["conv"]["bias"]
    conv._x, conv._out_shape = (
        snap["conv"]["x"], snap["conv"]["out_shape"]
    )
    bn._gamma, bn._beta = snap["bn"]["gamma"], snap["bn"]["beta"]
    bn._training = snap["bn"]["training"]
